<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require dirname(__DIR__,2).'/app/autoload.php';
use FMonitor2\Jobs\MariaDbWorkforceJobHandler;use FMonitor2\InstallationProcess\{BitrixWorkforceHistorySchemaMigration,MariaDbWorkforceSynchronization,WorkforceCatalogSchemaMigration};use FMonitor2\Workforce\{BitrixWorkforceDeliveryBatch,BitrixWorkforceDeliveryClient,BitrixWorkforceDeliveryResult,BitrixWorkforceDeliveryReason};
assertSameValue(true,class_exists(MariaDbWorkforceJobHandler::class),'INTENTIONAL_RED: workforce job handler delegates native synchronization');
final class JobFakeDelivery implements BitrixWorkforceDeliveryClient{public function __construct(private?array$rows,private?BitrixWorkforceDeliveryReason$reason=null){}public function fetch():BitrixWorkforceDeliveryResult{return$this->reason?new BitrixWorkforceDeliveryResult($this->reason,1,1,null):new BitrixWorkforceDeliveryResult(null,1,1,new BitrixWorkforceDeliveryBatch(count($this->rows??[]),$this->rows??[]));}}
function wjhWorker():array{return['ID'=>'501','ACTIVE'=>true,'LAST_NAME'=>'Иванов','NAME'=>'Иван','SECOND_NAME'=>'','WORK_POSITION'=>'Монтажник','EMAIL'=>'tab001042@example.test','UF_XING'=>'001042','UF_DEPARTMENT'=>[71],'UF_EMPLOYMENT_DATE'=>null];}
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$name='t_workforce_job_'.bin2hex(random_bytes(5));$admin=new mysqli($host,$user,$password,'',$port);$admin->query("CREATE DATABASE `{$name}` DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$db=new mysqli($host,$user,$password,$name,$port);$p='handler_';
try{WorkforceCatalogSchemaMigration::apply($db,$p);BitrixWorkforceHistorySchemaMigration::apply($db,$p);$sync=new MariaDbWorkforceSynchronization($db,$p);$success=new MariaDbWorkforceJobHandler($sync,new JobFakeDelivery([wjhWorker()]));$job=['jobId'=>91,'jobIdentity'=>'018f47ba-2f6d-4f80-8f42-0b37657fd901','jobType'=>'workforce.sync','payloadVersion'=>1,'payload'=>['scheduleSlot'=>'2026-09-09T10'],'attempt'=>1];$result=$success->handle($job);assertSameValue(['completed',1,1],[$result['status'],$result['delivered'],$result['materialChanges']],'handler preserves native full publication result');$before=$db->query("SELECT * FROM `{$p}fm2_workforce_observations` ORDER BY id")->fetch_all(MYSQLI_ASSOC);assertSameValue($result,$success->handle(array_replace($job,['attempt'=>2])),'same job identity retry returns durable sync result');assertSameValue($before,$db->query("SELECT * FROM `{$p}fm2_workforce_observations` ORDER BY id")->fetch_all(MYSQLI_ASSOC),'retry duplicates no observations');$failed=new MariaDbWorkforceJobHandler($sync,new JobFakeDelivery(null,BitrixWorkforceDeliveryReason::TransportFailed));$failure=$failed->handle(array_replace($job,['jobIdentity'=>'018f47ba-2f6d-4f80-8f42-0b37657fd902','attempt'=>1]));assertSameValue(['retryable','DELIVERY_TRANSPORT_FAILED'],[$failure['status'],$failure['failureCode']],'delivery failure maps to queue retry without partial facts');assertSameValue($before,$db->query("SELECT * FROM `{$p}fm2_workforce_observations` ORDER BY id")->fetch_all(MYSQLI_ASSOC),'failed fake delivery publishes no workforce observations');echo"PASS: DURABLE-BACKGROUND-JOBS-001 workforce handler preserves native synchronization\n";
}finally{$db->close();$admin->query("DROP DATABASE IF EXISTS `{$name}`");$admin->close();}
